function parseMatchTime(timeStr, dateStr) {
  // timeStr like "17:00 UTC-4" or "21:00 UTC-6"
  // Returns local Norway/Iceland time (UTC+2)
  if (!timeStr) return null;
  const parts = timeStr.split(" ");
  const [hStr, mStr] = parts[0].split(":");
  const h = parseInt(hStr);
  const m = parseInt(mStr || "0");
  const offsetMatch = parts[1] && parts[1].match(/UTC([+-]\d+)/);
  const offset = offsetMatch ? parseInt(offsetMatch[1]) : -4;
  // Convert to UTC then to UTC+2
  const utcH = h - offset;
  const localH = utcH + 2; // Norway/Iceland UTC+2
  const dayOverflow = localH >= 24;
  const displayH = ((localH % 24) + 24) % 24;
  const suffix = displayH >= 12 ? "pm" : "am";
  const h12 = displayH % 12 || 12;
  const timeDisplay = `${h12}:${m.toString().padStart(2,"0")}${suffix}`;
  return { display: timeDisplay + (dayOverflow ? " +1" : ""), isLate: dayOverflow || displayH < 6, localH: dayOverflow ? localH : displayH };
}

function getHighlight(team1, team2) {
  for (const [team, style] of Object.entries(HIGHLIGHT_TEAMS)) {
    if (team1?.includes(team) || team2?.includes(team)) return { team, ...style };
  }
  return null;
}

function formatDateKey(dateStr) {
  // "2026-06-29" -> "2026-06-29"
  return dateStr;
}

function getStageLabel(round, group) {
  if (group) return group;
  if (round?.includes("Round of 32")) return "R32";
  if (round?.includes("Round of 16")) return "R16";
  if (round?.includes("Quarter")) return "QF";
  if (round?.includes("Semi")) return "SF";
  if (round?.includes("Final")) return "Final";
  return round || "";
}

const STAGE_COLORS = {
  "Group A": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group B": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group C": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group D": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group E": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group F": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group G": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group H": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group I": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group J": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group K": { bg: "#EDE9FE", text: "#4C1D95" },
  "Group L": { bg: "#EDE9FE", text: "#4C1D95" },
  "R32":     { bg: "#E6F1FB", text: "#0C447C" },
  "R16":     { bg: "#FEF3DC", text: "#7A4300" },
  "QF":      { bg: "#FAC775", text: "#633806" },
  "SF":      { bg: "#FFEBEE", text: "#C62828" },
  "Final":   { bg: "#1a1a1a", text: "#FAC775" },
};

function MatchRow({ match }) {
  const parsed = parseMatchTime(match.time, match.date);
  const hl = getHighlight(match.team1, match.team2);
  const stage = getStageLabel(match.round, match.group);
  const sc = STAGE_COLORS[stage] || { bg: "#F1EFE8", text: "#5F5E5A" };
  const hasScore = match.score?.ft;
  const score = hasScore ? `${match.score.ft[0]} – ${match.score.ft[1]}` : null;

  return (
    <div style={{
      padding: "10px 14px",
      borderBottom: "1px solid #f8f7f4",
      background: hl ? hl.bg : "#fff",
      borderLeft: hl ? `3px solid ${hl.color}` : "3px solid transparent",
    }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 5, flexWrap: "wrap", marginBottom: 2 }}>
            <span style={{ fontSize: 13, fontWeight: hl ? 800 : 600, color: "#1a1a1a" }}>
              {hl && hl.flag + " "}{match.team1} vs {match.team2}
            </span>
          </div>
          <div style={{ display: "flex", gap: 5, flexWrap: "wrap", alignItems: "center" }}>
            <span style={{ fontSize: 9.5, fontWeight: 700, padding: "2px 7px",
              borderRadius: 999, background: sc.bg, color: sc.text }}>{stage}</span>
            {parsed?.isLate && <span style={{ fontSize: 9, color: "#f59e0b", fontWeight: 700 }}>🌙 late night</span>}
            {match.ground && <span style={{ fontSize: 10, color: "#bbb" }}>{match.ground}</span>}
          </div>
        </div>
        <div style={{ textAlign: "right", flexShrink: 0 }}>
          {score ? (
            <div style={{ fontSize: 16, fontWeight: 800, color: "#085041" }}>{score}</div>
          ) : (
            <div style={{ fontSize: 14, fontWeight: 800, color: parsed?.isLate ? "#f59e0b" : "#1a1a1a" }}>
              {parsed?.display || "TBD"}
            </div>
          )}
          {match.time && !score && (
            <div style={{ fontSize: 9.5, color: "#bbb" }}>{match.time}</div>
          )}
          {score && (
            <div style={{ fontSize: 9.5, color: "#aaa" }}>FT</div>
          )}
        </div>
      </div>
    </div>
  );
}

